import {DemoStore,SCENARIOS,phaseInfo} from './store.js';
import {readPreferences,writePreferences} from './preferences.js';
import {SetupWizard,roomOptions,waitOptions} from './setup-ui.js';
import {PhoneGuide} from './phone.js';
let phoneGuide;
let storage;try{storage=window.localStorage;}catch{}
let preferences=readPreferences(storage), setupWizard, settingsDraft, noticedEpisode=null, priorityEpisode=null, priorityFocus=null;
const store=new DemoStore(preferences);
let state=store.snapshot(), page=location.hash.slice(1)||'overview', logFilter='all', search='', modal='', lastFocus=null, toastTimer;
const names={overview:'宿舍总览',activity:'人员感知',control:'空调与学习',devices:'设备管理',logs:'事件记录'};
if(!names[page])page='overview';
const paths={
 home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z M9 21v-8h6v8',
 grid:'M3 3h7v7H3Z M14 3h7v7h-7Z M3 14h7v7H3Z M14 14h7v7h-7Z',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 ac:'M4 4h16a1 1 0 0 1 1 1v7H3V5a1 1 0 0 1 1-1Z M3 9h18 M7 15v3c0 2-3 2-3 0 M12 15v6 M17 15v3c0 2 3 2 3 0',
 device:'M6 3h12v18H6Z M10 6h4 M11 17h2',
 logs:'M6 3h12v18H6Z M9 7h6 M9 11h6 M9 15h4',
 arrow:'m9 5 7 7-7 7',arrowRight:'M4 12h16 M14 6l6 6-6 6',
 leaf:'M4 20C1 4 12 2 21 3c1 12-3 18-12 15 M4 20 16 8',
 check:'m5 12 4 4L19 6',
 timer:'M9 2h6 M12 6v6l3 2 M20 13a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
 clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',
 play:'m8 4 12 8-12 8Z',pause:'M8 5v14 M16 5v14',
 settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',
 help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M9 9a3 3 0 1 1 4 2.83V14 M12 17h.01',
 reset:'M3 10a9 9 0 1 1 2 9 M3 4v6h6',
 enter:'M14 3h6v18h-6 M3 12h12 M10 7l5 5-5 5',
 exit:'M10 3H4v18h6 M9 12h12 M16 7l5 5-5 5',
 wifi:'M2 8a17 17 0 0 1 20 0 M5 12a12 12 0 0 1 14 0 M8 16a7 7 0 0 1 8 0 M12 20h.01',
 alert:'m12 3 10 18H2Z M12 9v5 M12 17h.01',
 close:'m6 6 12 12 M6 18 18 6',
 plus:'M12 5v14 M5 12h14',minus:'M5 12h14',
 door:'M4 21V3h12v18 M10 12h.01 M2 21h20',
 scan:'M8 3H3v5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5 M7 12h10',
 download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',
 search:'M19 19l-5-5 M16 9a7 7 0 1 1-14 0 7 7 0 0 1 14 0',
 shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z m-4 9 3 3 5-6',
 sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',
 bell:'M5 16V9a7 7 0 0 1 14 0v7l2 2H3Z M10 21h4',
 bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',
 code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',
 snow:'M12 2v20 M3.3 7l17.4 10 M3.3 17 20.7 7 M9 4l3 3 3-3 M9 20l3-3 3 3'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',ic='',value='',disabled=false)=>`<button class="btn ${cls}" data-action="${action}" ${value!==''?`data-value="${esc(value)}"`:''} ${disabled?'disabled':''}>${ic?icon(ic):''}${text}</button>`;
const badge=(text,color='green')=>`<span class="badge ${color}"><span class="status-dot"></span>${text}</span>`;
const fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
const time=t=>`${String(Math.floor(t/3600)%24).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(Math.floor(t)%60).padStart(2,'0')}`;
const countText=()=>state.count===null?'—':state.count;
function heading(title,sub,action=''){return `<div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function roomIllustration(){
 const six=state.roomCapacity===6;const beds=six?[[30,40],[225,40],[30,115],[225,115],[30,190],[225,190]]:[[30,42],[225,42],[30,154],[225,154]];
 return `<svg class="room-map" viewBox="0 0 340 290" role="img" aria-label="${state.roomCapacity} 人寝布局示意，${state.trusted?state.count+' 人':'人数待核对'}。床位不代表人员实际位置。"><defs><pattern id="floor" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0v28" fill="none" stroke="#dce8dc" stroke-width=".7"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="5" stdDeviation="6" flood-color="#658474" flood-opacity=".12"/></filter></defs><rect x="13" y="17" width="314" height="252" rx="15" fill="#edf2e9" stroke="#d7e2d3"/><rect x="24" y="29" width="292" height="228" rx="8" fill="url(#floor)"/>
 <path d="M27 119V29h286v228H192 M136 257H27V119" fill="none" stroke="#a9beb0" stroke-width="6" stroke-linejoin="round"/>
 <path d="M113 29h102" stroke="#b8d6d0" stroke-width="9"/><path d="M113 29h102" stroke="#f8fcf5" stroke-width="3"/>
 ${beds.map(([x,y],i)=>`<g class="map-bed" transform="translate(${x},${y}) scale(1,${six?.68:1})" filter="url(#shadow)"><rect x="9" y="2" width="64" height="86" rx="6" fill="#fffef9" stroke="#d4ddd0"/><rect x="15" y="8" width="52" height="19" rx="5" fill="#fff" stroke="#e2e8dc"/><rect x="12" y="33" width="58" height="49" rx="4" fill="${i===1?'#c0cdb5':'#d7e0cd'}"/><path d="M18 42h45" stroke="#f6f7ec" stroke-width="2"/></g>`).join('')}
 <rect x="133" y="99" width="74" height="88" rx="12" fill="#ddc9a9" stroke="#c9b796"/><rect x="142" y="106" width="56" height="73" rx="6" fill="#e9d8bd"/>
 <rect x="152" y="111" width="31" height="21" rx="2" fill="#f7f4eb"/><path d="M168 111v21" stroke="#d7cbb6"/>
 <circle cx="173" cy="157" r="9" fill="#6c9873"/><path d="m166 158 7-10 6 9" fill="#8bb18c"/>
 ${Array.from({length:state.roomCapacity},(_,i)=>{const x=i%2===0?119:220,y=(six?[80,80,150,150,223,223]:[90,90,200,200])[i];const occupied=state.trusted&&i<state.count;return `<g opacity="${occupied?1:.25}"><circle cx="${x}" cy="${y}" r="14" fill="${occupied?'#2e8063':'#a9bab0'}" stroke="#f6f8f0" stroke-width="3"/><circle cx="${x}" cy="${y-3}" r="4" fill="white"/><path d="M${x-6} ${y+7}a6 6 0 0 1 12 0" fill="white"/></g>`;}).join('')}
 <path d="M137 257v-48a48 48 0 0 1 48 48" fill="none" stroke="#b8c8b9" stroke-width="1.5" stroke-dasharray="4 3"/><path d="M137 257 ${state.door?'h49':'v-49'}" stroke="#a78d69" stroke-width="4"/>
 <rect x="135" y="270" width="58" height="5" rx="2" fill="${state.trace?'#65bb87':'#a9d9bd'}"/><text x="164" y="288" font-size="10" text-anchor="middle" fill="#7b9082">入口 · A / B</text>
 <rect x="142" y="41" width="56" height="13" rx="4" fill="white" stroke="#b5cabe"/><path d="M147 50h46" stroke="#9fbaa8"/><path d="M157 59q-4 5 0 10m13-10q-4 5 0 10m13-10q-4 5 0 10" fill="none" stroke="${state.ac==='standby'?'transparent':'#86bbaa'}" stroke-width="2"/>
 </svg>`;
}
function shell(){return `<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${icon('home')}</span><span>栖息<small>QIXI · DORM ASSISTANT</small></span></a><div class="workspace-label">我的宿舍</div><button class="room-selector" data-action="room">${icon('home')}<span>6号楼 · 608<small>${state.roomCapacity} 人寝 · 演示空间</small></span>${icon('arrow')}</button><div class="workspace-label nav-label">工作空间</div><nav aria-label="主导航">${Object.entries(names).map(([id,n])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon({overview:'grid',activity:'users',control:'ac',devices:'device',logs:'logs'}[id])}<span>${n}</span>${id==='logs'&&state.logs.some(l=>l.level==='warning')?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="little-note">${icon('leaf')}<span>让节能，成为日常。<small>每一次离开，都有照应</small></span></div><button class="nav-item" data-action="help">${icon('help')}<span>使用指南</span></button><button class="user-block" data-action="members"><span class="avatar">${esc(state.member[0])}</span><span>${esc(state.member)}<small>宿舍成员 · 模拟身份</small></span>${icon('settings')}</button></div></aside>
 <div class="workspace"><header class="topbar"><span class="breadcrumb">工作空间 <span>/</span> <b>${names[page]}</b></span><div class="top-actions"><span class="demo-badge"><span></span>交互演示 · 无真实设备</span><button class="icon-btn phone-entry" data-action="phone-guide" aria-label="桌面与提醒">${icon('bell')}</button><button class="icon-btn settings-entry" data-action="room" aria-label="房间与等待时间设置">${icon('settings')}</button><button class="small-avatar" data-action="members" aria-label="切换演示成员">${esc(state.member[0])}</button></div></header>
 <main id="main" tabindex="-1"><div class="page-title"><div><div class="eyebrow">${page==='overview'?'YOUR ROOM, IN BALANCE':'608 / DORM WORKSPACE'}</div><h1>${names[page]}${page==='overview'?'<span class="title-dot"></span>':''}</h1><p>${{overview:'有人时安心陪伴，离开后及时关照。',activity:'每一次进出，都有迹可循。',control:'从学习遥控器，到一次可靠的关机。',devices:'看清连接状态，找到需要处理的环节。',logs:'把每次变化和操作，记录清楚。'}[page]}</p></div>${btn('演示控制台','demo','primary','play')}</div>
 ${!state.cloud?`<div class="banner amber">${icon('wifi')}<span><strong>平台网络已断开（模拟）</strong>　下方为本地过程推演；真实断网时网页无法获得最新状态，本地计数与规则继续运行。</span>${btn('恢复','cloud','small')}</div>`:''}
 ${!navigator.onLine?'<div class="phone-offline">当前离线 · 下方为缓存的演示页面，数据不代表宿舍实时状态。</div>':''}${pageContent()}</main><footer class="page-footer"><span>${icon('shield')} 本页仅使用模拟数据，不连接或控制真实空调</span><span>栖息 · 让空间懂得节能</span></footer></div>
 <div class="demo-dock"><span class="dock-label">${icon('code')} 快速体验 <i>SIMULATOR</i></span><div class="dock-actions">${btn('进入一人','enter','dock-button','enter')}${btn('离开一人','leave','dock-button','exit')}${btn('+ 1 分钟','advance','dock-button','clock','60')}${btn('更多场景','demo','dock-button','settings')}</div><span class="dock-clock">${time(state.time)} <small>模拟时间 · ${state.speed}×</small></span><button class="icon-btn" data-action="play" aria-label="${state.playing?'暂停':'继续'}模拟时钟">${icon(state.playing?'pause':'play')}</button></div>`;}
function pageContent(){return ({overview,activity,control,devices,logs})[page]();}
function overview(){const [label,sub,color]=phaseInfo(state);const ac={running:'模拟运行中',standby:'模拟待机',unknown:'状态未知'}[state.ac];
 return `<div class="overview-grid"><section class="card room-card"><div class="card-top"><span class="tiny-label">${icon('home')} 608 房间状态</span>${badge(label,color)}</div><div class="room-body"><div class="occupancy"><span class="muted">当前在寝人数 ${!state.eg?'<span class="stale">最后记录</span>':''}</span><div class="big-count">${countText()}<span>人</span></div><span class="confidence ${!state.trusted?'warning':''}">${icon(state.trusted?'shield':'alert')}${state.trusted?'已校准 · 计数可信':'等待核对 · 请校准'}</span><div class="room-avatars">${state.members.map((m,i)=>`<span class="person-avatar ${state.trusted&&i<state.count?'present':''}" title="成员示意，不代表身份识别">${m[0]}</span>`).join('')}<small>仅示意在寝人数</small></div>${btn('校准人数','calibrate-modal','text-button','settings')}</div><div class="room-visual">${roomIllustration()}<span class="map-caption">空间示意 · 不代表实际人员位置</span></div></div><div class="room-foot"><span>${icon('door')} ${state.door?'门已关闭':'门已打开'}</span><span>${icon('scan')} ${state.trace?(state.trace.direction==='enter'?'A → B · 进入':'B → A · 离开'):'双红外待命'}</span><span>${icon('clock')} ${time(state.time)}</span></div></section>
 <section class="card climate-card"><div class="card-top"><span class="tiny-label">${icon('ac')} 空调与自动规则</span>${badge(ac,state.ac==='unknown'?'amber':'green')}</div><div class="ac-unit"><div class="ac-body"><span class="ac-brand">QIXI</span><span class="ac-indicator ${state.ac==='standby'?'off':''}"></span><div class="ac-grille"></div></div><div class="air-lines ${state.ac==='standby'?'off':''}"><i></i><i></i><i></i></div></div><div class="climate-copy"><h3>${state.ac==='standby'?'这一刻，刚好休息。':state.ac==='unknown'?'指令发出后，还需确认。':'舒适留给在寝的你。'}</h3><p>${state.ac==='standby'?'演示观察器已返回待机结果':'空房等待 '+state.waitMinutes+' 分钟，可提前确认关机'}</p></div><div class="climate-rule"><span>${icon('bolt')} 提前确认 · 到点自动关</span><button class="switch ${state.paused?'':'on'}" role="switch" aria-checked="${!state.paused}" aria-label="启用自动关机规则" data-action="pause"><span></span></button></div><button class="card-link" data-action="go" data-value="control">查看空调与学习 ${icon('arrowRight')}</button></section></div>
 ${flowCard()}
 <div class="phone-invite"><span>${icon('device')}</span><div><strong>把栖息放到手机桌面</strong><p>添加桌面图标，设置提醒，随时回到宿舍。</p></div>${btn('去设置','phone-guide','secondary small','arrowRight')}</div>
 <div class="metrics"><div class="metric"><span class="metric-icon green">${icon('enter')}</span><div><span>今日进入 <small>模拟</small></span><strong>${state.dayIn}<em>次</em></strong></div><span class="metric-note">门口通行记录</span></div><div class="metric"><span class="metric-icon blue">${icon('exit')}</span><div><span>今日离开 <small>模拟</small></span><strong>${state.dayOut}<em>次</em></strong></div><span class="metric-note">单人依次通行</span></div><div class="metric"><span class="metric-icon amber">${icon('timer')}</span><div><span>空房等待</span><strong>${state.waitMinutes}<em>分钟</em></strong></div><span class="metric-note">连续满足才执行</span></div><div class="metric"><span class="metric-icon violet">${icon('device')}</span><div><span>核心设备在线</span><strong>${Number(state.eg)+Number(state.esp)}<em>/ 2</em></strong></div><span class="metric-note">模拟连接状态</span></div></div>
 <div class="bottom-grid"><section class="card recent-card">${heading('最近动态','房间里的每个变化，都有记录',btn('全部记录','go','text-button','arrowRight','logs'))}${eventList(state.logs.slice(0,4))}</section><section class="card connection-card">${heading('设备连接','本地协作，无需依赖网络',btn('管理','go','text-button','arrowRight','devices'))}${miniDevice('device','EG800Z 主控','人数统计 · 自动决策',state.eg)}${miniDevice('ac','ESP8266 执行器','红外学习 · 指令发送',state.esp)}<div class="connection-note">${icon('shield')} ${state.paired?'关机配置已模拟验证':'关机配置尚未验证'}<button data-action="go" data-value="control">查看 ${icon('arrow')}</button></div></section></div>`;
}
function flowCard(){const [label,sub,color]=phaseInfo(state);const number=fmt(state.remaining??state.delaySeconds);const pending=['requested','accepted','executing','sent'].includes(state.phase);const idx=state.phase==='success'?3:pending?2:state.phase==='countdown'?1:0;
return `<section class="card flow-card ${color}"><div class="flow-heading"><span class="flow-icon">${icon(state.phase==='success'?'check':state.phase==='untrusted'?'alert':'timer')}</span><div><h3>${label}</h3><p>${sub}</p></div>${state.phase==='countdown'?`<div class="countdown">${number}<small>到点自动关机</small></div>`:btn(state.paused?'恢复自动':'暂停自动','pause','secondary small',state.paused?'play':'pause')}</div><div class="flow-steps">${['确认空房','等待 '+state.waitMinutes+' 分钟','发送 OFF 指令','查看执行结果'].map((t,i)=>`<div class="flow-step ${i<=idx?'reached':''}"><span>${i<idx?icon('check'):i+1}</span><b>${t}</b>${i<3?'<i></i>':''}</div>`).join('')}</div>${state.phase==='countdown'?`<div class="inline-actions">${btn('提前确认关机','confirm-modal','primary small','bell')}${btn('暂停本次关机','cancel','secondary small')}<small>不确认也会到点自动关闭；继续等待不会取消任务。</small></div>`:''}${['untrusted','unknown-count'].includes(state.phase)?`<div class="inline-actions"><span>${esc(state.reason)}</span>${btn('现在校准','calibrate-modal','secondary small')}</div>`:''}${['failed','unknown','expired','success'].includes(state.phase)?`<div class="inline-actions"><span>${esc(state.command?.reason||'')}</span>${btn('查看记录','go','text-button small','arrowRight','logs')}</div>`:''}</section>`;
}
function miniDevice(ic,title,desc,on){return `<div class="mini-device"><span class="device-symbol">${icon(ic)}</span><div><strong>${title}</strong><small>${desc}</small></div>${badge(on?'在线 · 模拟':'离线 · 模拟',on?'green':'red')}</div>`;}
function eventList(events){return `<div class="event-list">${events.length?events.map(e=>`<div class="event"><span class="event-icon ${e.level==='warning'?'amber':''}">${icon(e.type==='passage'?'users':e.type==='command'?'ac':e.type==='device'?'wifi':e.type==='user'?'users':e.level==='warning'?'alert':'check')}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.detail)}</p></div><time>${time(e.time)}</time></div>`).join(''):'<div class="empty">'+icon('logs')+'<h3>还没有匹配的记录</h3><p>尝试调整筛选条件，或模拟一次操作。</p></div>'}</div>`;}
function activity(){return `<div class="two-col"><section class="card padded">${heading('人数与可信状态','人数从人工校准值出发，根据进出累计') }<div class="activity-count"><strong>${countText()}</strong><span>人</span>${badge(state.trusted?'计数可信':'需要校准',state.trusted?'green':'amber')}</div><p class="muted">${state.trusted?'每次完整进出才结算一次。发生歧义时，暂停自动关机。':esc(state.reason)}</p><div class="inline-actions">${btn('校准人数','calibrate-modal','primary','settings')}${btn('模拟歧义通行','ambiguous','secondary','alert')}</div></section><section class="card padded">${heading('门口感知','A 靠走廊，B 靠室内；依次触发判断方向')}<div class="sensor-track"><span>走廊</span><div class="sensor ${state.trace?'lit':''}">A<small>红外</small></div><span class="sensor-arrow">${state.trace?.direction==='leave'?'←':'→'}</span><div class="sensor ${state.trace?'lit':''}">B<small>红外</small></div><span>室内</span></div><p class="center muted">${state.trace?state.trace.direction==='enter'?'A → B：模拟进入':'B → A：模拟离开':'等待下一次完整通行'}</p><div class="inline-actions">${btn('进入一人','enter','secondary','enter')}${btn('离开一人','leave','secondary','exit')}${btn(state.door?'打开门':'关闭门','door','text-button','door')}</div></section></div><section class="card table-card">${heading('通行记录','每条记录对应一次模拟通行')}<div class="table-scroll"><table><thead><tr><th>模拟时间</th><th>通行方向</th><th>传感器顺序</th><th>变化后人数</th><th>来源</th></tr></thead><tbody>${state.passages.map(p=>`<tr><td class="mono">${time(p.time)}</td><td><span class="direction ${p.direction}">${icon(p.direction)}${p.direction==='enter'?'进入':'离开'}</span></td><td class="mono">${p.direction==='enter'?'A → B':'B → A'}</td><td>${p.count??'未知'} 人</td><td><span class="tag">模拟事件</span></td></tr>`).join('')}</tbody></table></div></section><div class="info-strip">${icon('help')} 双红外适用于单人依次通行；两人紧跟、并排或同时漏检可能无法准确识别。成员头像不表示身份识别。</div>`;}
const learningSteps=[['采集第一次 OFF','将原遥控器对准接收头，按下关机。本演示用按钮模拟捕获。','模拟捕获信号'],['再次采集，核对信号','重新建立遥控器的开机状态，再采一次关机，比较完整数据。','模拟第二次捕获'],['验证：开机能够关闭','向运行中的空调发送 OFF，现场应观察到正常关机。','模拟观察：已关机'],['验证：已关不会重开','空调已关闭，再次发送同一 OFF，应该仍保持关闭。','模拟观察：仍关闭'],['验证：其他设置也能关','改变原运行模式或温度，再次确认 OFF 能正确关闭。','模拟观察：验证通过'],['保存关机配置','三项模拟观察均通过。保存后需要重新校准人数。','保存模拟配置']];
function control(){const learn=state.learning;return `${flowCard()}<div class="two-col control-grid"><section class="card padded">${heading('关机规则','可提前确认；无人操作，到点自动关闭',btn('修改设置','room','text-button','settings'))}<div class="setting-row"><div><strong>连续空房等待</strong><p>人数为 0，且门关稳定后开始</p></div><span class="rule-value">${state.waitMinutes} <small>分钟</small></span></div><div class="policy-explainer"><span>${icon('bell')} 空房后优先提醒</span><p>等待期间，可在置顶弹窗中提前确认。未确认时，倒计时归零仍自动关机；明确暂停才会停止。</p></div><div class="setting-row"><div><strong>自动关机规则</strong><p>${state.paused?'已暂停，恢复后重新计时':'检测到进入、门开或异常会取消倒计时'}</p></div><button class="switch ${state.paused?'':'on'}" role="switch" aria-checked="${!state.paused}" aria-label="自动规则开关" data-action="pause"><span></span></button></div><div class="note">${icon('shield')} 网页演示状态不构成真实设备执行许可。实际项目由 EG800Z 作最终决策。</div></section><section class="card padded">${heading('当前关机配置','一台空调，一份经过验证的 OFF',badge(state.paired?'已模拟验证':'未验证',state.paired?'green':'amber'))}<div class="profile-art">${icon('ac')}<div><h3>608 空调 · 演示样机</h3><p>具体品牌 / 协议待实测</p></div></div><div class="definition"><span>配置编号</span><b class="mono">${state.paired?state.profile:'尚未保存'}</b><span>独立 OFF</span><b>${state.paired?'演示验证通过':'待验证'}</b><span>真实空调反馈</span><b>尚未接入</b></div>${btn(learn?'继续学习':'重新学习遥控器',learn?'scroll-learning':'learn-modal','secondary full','scan','',!state.eg||!state.esp)}<p class="footnote">学习通过仅代表演示流程完成，不表示真实遥控协议已验证。</p></section></div>
 <section class="card padded learning-card" id="learning">${heading('红外学习向导','跟着步骤完成配对，先验证，再保存。',`<span class="tag">全程模拟</span>`)}${learn?`<div class="learning-progress">${learningSteps.map((x,i)=>`<span class="${i<learn.step?'done':i===learn.step?'current':''}">${i<learn.step?icon('check'):i+1}</span>`).join('')}</div><div class="learning-main"><span class="learning-illustration">${icon(learn.failed?'alert':'scan')}</span><div><span class="eyebrow">STEP ${learn.step+1} / 6</span><h3>${learn.failed?'这一步没有通过':learningSteps[learn.step][0]}</h3><p>${learn.failed?'记录仍保留，配置不会被标记为有效。重试本步骤后才能继续。':learningSteps[learn.step][1]}</p><div class="inline-actions">${btn(learn.failed?'重试当前步骤':learningSteps[learn.step][2],learn.failed?'learning-retry':'learning-next','primary',learn.failed?'reset':'check')}${!learn.failed&&learn.step>=2&&learn.step<5?btn('模拟未通过','learning-fail','secondary'):''}${btn('退出学习','learning-abort','text-button')}</div></div></div>`:`<div class="learning-empty"><div class="learning-illustration">${icon('scan')}</div><div><h3>让设备学会，如何正确关机。</h3><p>两次采集信号，三次 OFF 验证，再保存配置。<br>先体验完整流程，未来再连接真实红外设备。</p></div>${btn('开始模拟学习','learn-modal','primary','arrowRight','',!state.eg||!state.esp)}</div>`}</section>`;}
function devices(){return `<div class="banner neutral">${icon('device')}<span>这里展示设备连接的模拟状态。设备离线与平台断网是两种不同情况。</span></div><div class="device-grid">${[
['device','EG800Z','决策主控','采集人数、判断空房、授权关机',state.eg,'eg'],['ac','ESP8266','红外执行器','学习遥控信号、发射 OFF',state.esp,'esp'],['scan','双红外 + 门磁','门口感知','记录 A/B 先后顺序与门状态',state.eg,'door'],['wifi','平台网络','状态同步演示','断开后，本地逻辑仍继续推演',state.cloud,'cloud']
].map(([ic,title,role,desc,on,act])=>`<section class="card device-card"><div class="card-top"><span class="large-device-icon">${icon(ic)}</span>${badge(on?'在线 · 模拟':'离线 · 模拟',on?'green':'red')}</div><h2>${title}</h2><span class="tiny-label">${role}</span><p>${desc}</p><div class="device-details"><span>所在位置</span><b>6号楼 608</b><span>数据来源</span><b>浏览器模拟器</b><span>${act==='door'?'门磁状态':'连接状态'}</span><b>${act==='door'?(state.door?'门已关闭':'门已打开'):(on?'模拟连接正常':'已模拟断开')}</b></div><div class="inline-actions">${btn(act==='door'?(state.door?'模拟开门':'模拟关门'):(on?'模拟断开':'恢复连接'),act,'secondary small',act==='door'?'door':'wifi')}${act==='eg'?btn('模拟重启','reboot-modal','text-button small','reset'):''}</div></section>`).join('')}</div><section class="card padded">${heading('模拟结果观察器','用于讲解“发出指令”和“空调关机”的区别')}<div class="setting-row"><div><strong>返回模拟空调结果</strong><p>开启时生成演示反馈；关闭后，发送完成仍显示结果未知。</p></div><button class="switch ${state.feedback?'on':''}" data-action="feedback" role="switch" aria-checked="${state.feedback}" aria-label="模拟结果观察器"><span></span></button></div><div class="note">这个观察器是演示软件，不是已经购买或接入的独立硬件。真实项目暂时没有空调内部状态反馈。</div></section>`;}
function logs(){const filtered=state.logs.filter(e=>(logFilter==='all'||e.type===logFilter||(logFilter==='warning'&&e.level==='warning'))&&(`${e.title} ${e.detail}`.toLowerCase().includes(search.toLowerCase())));return `<section class="card padded logs-card">${heading('事件与操作记录','按模拟时间排列 · 最多保留最近 250 条',btn('导出记录','export','secondary small','download'))}<div class="log-toolbar"><div class="filter-tabs">${[['all','全部'],['passage','人员'],['command','执行'],['user','操作'],['device','设备'],['warning','异常']].map(([v,t])=>btn(t,'filter',logFilter===v?'active':'','',v)).join('')}</div><label class="search-field">${icon('search')}<input id="log-search" placeholder="搜索事件或原因" aria-label="搜索事件或原因" value="${esc(search)}"></label></div><div class="log-meta">${filtered.length} 条记录 <span>演示数据 · ${time(state.time)}</span></div>${eventList(filtered)}</section>${state.command?`<section class="card padded command-detail">${heading('最近一次模拟命令','请求、执行与结果分别记录')}<div class="definition"><span>命令编号</span><b class="mono">${state.command.id}</b><span>执行状态</span><b>${esc(state.command.status)}</b><span>启动会话</span><b>${state.command.session}</b><span>配置编号</span><b>${state.command.profile}</b></div>${btn('模拟重复提交','duplicate','secondary small','reset')}<p class="footnote">重复提交只产生拒绝记录，不会再次发射。此处是模拟逻辑，不能据此声明真实设备通信已经验证。</p></section>`:''}`;}
function focusKey(el){
  if(!el||el===document.body)return null;
  if(el.id)return {id:el.id};
  if(el.dataset?.action){const matches=[...document.querySelectorAll('#app [data-action]')].filter(x=>x.dataset.action===el.dataset.action&&x.dataset.value===el.dataset.value);return {action:el.dataset.action,value:el.dataset.value,index:matches.indexOf(el)};}
  if(el.tagName==='A')return {href:el.getAttribute('href')};
  return null;
}
function resolveFocus(key){
  if(!key)return null;
  if(key.id)return document.getElementById(key.id);
  if(key.href)return [...document.querySelectorAll('#app a')].find(x=>x.getAttribute('href')===key.href);
  return [...document.querySelectorAll('#app [data-action]')].filter(x=>x.dataset.action===key.action&&x.dataset.value===key.value)[Math.max(0,key.index)];
}
function render(){
  const active=document.activeElement,key=focusKey(active),inside=document.getElementById('app').contains(active);
  const sel=active?.tagName==='INPUT'?[active.selectionStart,active.selectionEnd]:null;
  document.getElementById('app').innerHTML=shell();
  if(inside&&!modal){const target=resolveFocus(key);if(target){target.focus({preventScroll:true});if(sel&&target.type!=='number')target.setSelectionRange(...sel);}}
  if(modal==='demo')updateDemoLive();
}
function notify(text){if(!text)return;clearTimeout(toastTimer);const t=document.getElementById('toast');t.innerHTML=icon('check')+'<span>'+esc(text)+'</span>';t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),3200);}
function navigate(next){if(!names[next])return;closeModal();page=next;if(location.hash.slice(1)!==next)location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(names[n]&&n!==page)navigate(n);});
function closeModal(){const dialog=document.querySelector('#overlay dialog');if(dialog){dialog.close();dialog.remove();}modal='';const target=resolveFocus(lastFocus);if(target)target.focus({preventScroll:true});}
function openModal(type){if(type==='confirm'){openPriority(true);return;}if(type==='room')settingsDraft={roomCapacity:state.roomCapacity,waitMinutes:state.waitMinutes};const trigger=focusKey(document.activeElement);closeModal();lastFocus=trigger;modal=type;const content=modalContent(type);document.getElementById('overlay').innerHTML=`<dialog class="${type==='demo'?'drawer':'modal'}" aria-labelledby="dialog-title"><div class="dialog-top"><div><span class="eyebrow">${type==='demo'?'DEMO STUDIO':'QIXI / 608'}</span><h2 id="dialog-title">${content.title}</h2></div><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div>${content.body}</dialog>`;const d=document.querySelector('#overlay dialog');d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});d.showModal();}
function modalContent(type){
 if(type==='demo')return {title:'演示控制台',body:`<p class="dialog-intro">像操作真实宿舍一样，体验每一种状态。<br>所有操作仅作用于本页模拟器。</p><div class="sim-clock"><span>模拟时间</span><strong id="demo-time">${time(state.time)}</strong><div class="speed-buttons">${[1,15,60].map(v=>btn(v+'×','speed',state.speed===v?'selected':'','',v)).join('')}</div><div class="inline-actions">${btn(state.playing?'暂停时钟':'继续时钟','play','secondary small','pause')}${btn('+ 1 分钟','advance','secondary small','clock','60')}${btn('+ 15 分钟','advance','secondary small','timer','900')}</div></div><div class="demo-live" id="demo-live">${phaseInfo(state)[0]}</div><h3 class="drawer-label">选择一个演示场景 <small>每次载入都会重置数据</small></h3><div class="scenarios">${SCENARIOS.map(sc=>`<button class="scenario ${state.scenario===sc.id?'selected':''}" data-action="scenario" data-value="${sc.id}"><span>${icon(sc.icon)}</span><div><strong>${sc.name}</strong><small>${sc.desc}</small></div>${icon('arrow')}</button>`).join('')}</div><h3 class="drawer-label">模拟输入</h3><div class="demo-inputs">${btn('进入一人','enter','secondary','enter')}${btn('离开一人','leave','secondary','exit')}${btn('开 / 关门','door','secondary','door')}${btn('歧义通行','ambiguous','secondary','alert')}${btn('平台断网 / 恢复','cloud','secondary','wifi')}${btn('重复命令','duplicate','secondary','reset')}</div><div class="drawer-footer">${btn('重置全部演示','reset-modal','secondary full','reset')}</div>`};
 if(type==='calibrate')return{title:'校准实际人数',body:`<p class="dialog-intro">先确认宿舍里有几个人，再提交校准。校准会取消旧倒计时，重新判断空房条件。</p><form id="calibrate-form"><label class="field-label" for="count-input">当前实际人数</label><div class="number-stepper"><button type="button" data-action="count-minus" aria-label="减少人数">${icon('minus')}</button><input id="count-input" type="number" min="0" max="8" step="1" value="${state.count??0}" required aria-label="当前实际人数"><button type="button" data-action="count-plus" aria-label="增加人数">${icon('plus')}</button></div><p class="footnote">演示可输入 0～8 人。未知不等于 0 人。</p><div class="note">${icon('shield')} 这会修改模拟人数，不会修改真实开发板。</div><div class="dialog-actions">${btn('取消','close','secondary')}<button class="btn primary" type="submit" ${!state.eg?'disabled':''}>确认校准</button></div>${!state.eg?'<p class="error-text">主控离线，请先恢复连接。</p>':''}</form>`};
 if(type==='learn')return{title:'开始学习遥控器？',body:`<p class="dialog-intro">学习期间暂停自动关机，旧配置暂时停用。完成两次采集和三次验证后，才能保存新配置。</p><div class="note">本次使用模拟信号和模拟观察，不需要真实遥控器。完成后请重新校准人数。</div><div class="dialog-actions">${btn('暂不开始','close','secondary')}${btn('开始模拟学习','learning-start','primary','scan')}</div>`};
 if(type==='reboot')return{title:'模拟主控重启',body:`<p class="dialog-intro">人数将变为“未知”，旧计时和未执行许可作废。重新校准后才能恢复自动规则。</p><div class="dialog-actions">${btn('取消','close','secondary')}${btn('模拟重启','reboot','primary','reset')}</div>`};
 if(type==='reset')return{title:'重新开始演示？',body:`<p class="dialog-intro">将恢复到 3 人在寝、空调模拟运行的初始场景，并清空本轮操作记录。需要留存的记录可先到事件页导出。</p><div class="dialog-actions">${btn('继续当前演示','close','secondary')}${btn('重置演示','reset','primary','reset')}</div>`};
 if(type==='members')return{title:'一起管理这个小空间',body:`<p class="dialog-intro">6号楼 608 · ${state.roomCapacity} 位演示成员。任一成员都可以暂停或否决本次模拟关机。</p><div class="member-list">${state.members.map(m=>`<button data-action="member" data-value="${m}"><span class="avatar">${m[0]}</span><span><strong>${m}</strong><small>宿舍成员 · 模拟身份</small></span>${m===state.member?badge('当前'):'<span class="muted">切换体验</span>'}</button>`).join('')}</div><div class="note">这里只切换演示中的操作人名称，不是真实登录或权限认证。</div>`};
 if(type==='room')return{title:'房间与等待时间',body:`<p class="dialog-intro">房型改变布局与成员数量，实际在寝人数不会自动改变。设置保存在当前浏览器。</p><form id="settings-form"><label class="field-label">寝室类型</label><div id="settings-room-options">${roomOptions(settingsDraft.roomCapacity)}</div><label class="field-label settings-wait-label">空房后等待多久？</label>${waitOptions(settingsDraft.waitMinutes)}<div class="note">等待期间可以提前确认，到点仍自动关机。修改时长会取消旧倒计时，重新按新时长等待。</div><p class="settings-error error-text" role="alert"></p><div class="dialog-actions">${btn('取消','close','secondary')}<button class="btn primary" type="submit">保存设置</button></div></form><button class="btn text-button full replay-guide" data-action="replay-guide">重新查看新手引导和红外教程</button>`};
 return{title:'两分钟，了解栖息',body:`<div class="guide-step"><span>1</span><div><h3>先看看，谁在寝</h3><p>用底部“进入一人 / 离开一人”观察人数变化。数不准时，可以手动校准。</p></div></div><div class="guide-step"><span>2</span><div><h3>最后一人离开后</h3><p>门关稳定，开始 ${state.waitMinutes} 分钟倒计时。用演示控制台加速时间，或载入“即将自动关机”。</p></div></div><div class="guide-step"><span>3</span><div><h3>看看系统如何应对变化</h3><p>有人回来会取消计时；歧义、重启和执行失败都有不同的提示与处理。</p></div></div><div class="note">等待期间可提前确认，到预设时间仍会自动关闭；有人回来或明确暂停会取消。所有空调结果均为模拟。</div>${btn('体验即将关机','guided','primary full','play')}<div class="replay-guide">${btn('添加桌面与设置提醒','phone-guide','secondary full','bell')}</div>`};
}
function updateDemoLive(){const t=document.getElementById('demo-time'),l=document.getElementById('demo-live');if(t)t.textContent=time(state.time);if(l)l.textContent=phaseInfo(state)[0]+(state.remaining!==null?' · '+fmt(state.remaining):'')+' · '+(state.playing?'时钟运行':'时钟暂停');document.querySelectorAll('.speed-buttons [data-action="speed"]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.value)===state.speed));const play=document.querySelector('dialog [data-action="play"]');if(play)play.innerHTML=icon(state.playing?'pause':'play')+(state.playing?'暂停时钟':'继续时钟');}
function closePriority(){const d=document.querySelector('#priority-layer dialog');if(!d){priorityEpisode=null;return;}d.close();d.remove();priorityEpisode=null;const previous=priorityFocus;priorityFocus=null;if(previous?.isConnected)previous.focus({preventScroll:true});else if(!modal)resolveFocus({action:'confirm-modal',index:0})?.focus({preventScroll:true});}
function openPriority(force=false){
 if(!preferences.onboardingDone||!store.canConfirm())return;
 if(!force&&noticedEpisode===state.emptyId)return;
 noticedEpisode=state.emptyId;priorityEpisode=state.emptyId;
 let root=document.getElementById('priority-layer');if(!root){root=document.createElement('div');root.id='priority-layer';document.body.append(root);}
 if(root.querySelector('dialog')){updatePriority();return;}
 priorityFocus=document.activeElement;
 root.innerHTML=`<dialog class="modal priority-modal" role="alertdialog" aria-modal="true" aria-labelledby="priority-title" aria-describedby="priority-description"><div class="priority-topline"><span>${icon('bell')} 关机优先提醒</span><span>模拟操作</span></div><div class="priority-symbol">${icon('ac')}</div><h2 id="priority-title">宿舍已空，现在关空调吗？</h2><p id="priority-description">可以提前确认关机。未确认时，预设等待时间结束后仍会自动关闭。</p><div class="priority-timer"><span>距离自动关机</span><strong id="priority-remaining">${fmt(state.remaining)}</strong><small>已设等待 ${state.waitMinutes} 分钟 · 门已关闭 · 人数可信</small></div><button class="btn primary full priority-confirm" data-priority="confirm">${icon('check')} 立即确认关机</button><button class="btn secondary full" data-priority="wait" autofocus>继续等待，到点自动关机</button><button class="btn text-button full priority-pause" data-priority="pause">暂停本次关机</button><p class="priority-footnote">继续等待不取消任务；有人进入、门打开或出现异常时，自动停止本次倒计时。</p></dialog>`;
 const d=root.querySelector('dialog');d.addEventListener('cancel',e=>{e.preventDefault();closePriority();notify('已收起提醒，倒计时继续，到点自动关机');});
 d.addEventListener('click',e=>{const b=e.target.closest('[data-priority]');if(!b)return;const a=b.dataset.priority,valid=priorityEpisode===state.emptyId&&store.canConfirm();closePriority();if(a==='wait'){notify('继续等待，到预设时间自动关机');return;}if(!valid){notify('条件已变化，本次确认已失效');return;}store.act(a==='confirm'?'confirm':'cancel');notify(state.notice);});
 d.showModal();
}
function updatePriority(){const el=document.getElementById('priority-remaining');if(el)el.textContent=fmt(Math.max(0,state.remaining??0));}
function syncPriority(){
 if(!store.canConfirm()){closePriority();return;}
 if(priorityEpisode!==null&&priorityEpisode!==state.emptyId)closePriority();
 if(priorityEpisode!==null)updatePriority();else openPriority();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value;
 if(a==='phone-guide'){closeModal();phoneGuide?.open();return;}
 if(a==='close'){closeModal();return;}
 if(a==='replay-guide'){closeModal();setupWizard.open(true);return;}
 if(a==='go'){navigate(v);return;}
 if(['demo','help','members','room'].includes(a)){openModal(a);return;}
 if(a.endsWith('-modal')){openModal(a.replace('-modal',''));return;}
 if(a==='scroll-learning'){document.getElementById('learning')?.scrollIntoView({behavior:'smooth'});return;}
 if(a==='count-minus'||a==='count-plus'){const el=document.getElementById('count-input');el.value=Math.max(0,Math.min(8,Number(el.value)+(a==='count-plus'?1:-1)));return;}
 if(a==='filter'){logFilter=v;render();return;}
 if(a==='export'){const data=JSON.stringify({...store.snapshot(),notice:'全部为模拟记录，无真实设备操作',room:'6号楼608',exported:new Date().toISOString()},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='栖息-模拟事件记录.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('模拟记录已导出为 JSON');return;}
 if(a==='advance'){store.advance(Number(v));notify('模拟时间已推进 '+Number(v)/60+' 分钟');return;}
 if(a==='reset'){closeModal();store.reset();navigate('overview');notify('已重置到初始演示');return;}
 if(a==='guided'){closeModal();store.reset('near');navigate('overview');notify('已载入 10 秒倒计时，稍后查看模拟关机结果');return;}
 if(a==='scenario'){closeModal();navigate('overview');store.reset(v);notify(state.notice);return;}
 if(a==='learning-start'){closeModal();store.act(a);navigate('control');notify(state.notice);return;}
 if(a==='reboot'||a==='member')closeModal();
 store.act(a,v);notify(state.notice);
});
document.addEventListener('input',e=>{if(e.target.id==='log-search'){search=e.target.value;render();}});
document.addEventListener('submit',e=>{
 if(e.target.id==='calibrate-form'){e.preventDefault();const n=Number(document.getElementById('count-input').value);closeModal();store.act('calibrate',n);notify(state.notice);}
 if(e.target.id==='settings-form'){e.preventDefault();settingsDraft.waitMinutes=Number(e.target.elements['wait-minutes'].value);if(saveSettings(settingsDraft)){closeModal();}else e.target.querySelector('.settings-error').textContent=state.notice;}
});
document.addEventListener('change',e=>{if(e.target.closest('#settings-form')&&e.target.name==='room-capacity'){settingsDraft.roomCapacity=Number(e.target.value);document.getElementById('settings-room-options').innerHTML=roomOptions(settingsDraft.roomCapacity);document.querySelector(`#settings-form input[value="${settingsDraft.roomCapacity}"]`).focus();}});
document.addEventListener('click',e=>{const preset=e.target.closest('#settings-form [data-wait-preset]');if(preset){settingsDraft.waitMinutes=Number(preset.dataset.waitPreset);document.querySelector('#settings-form [name="wait-minutes"]').value=settingsDraft.waitMinutes;document.querySelectorAll('#settings-form [data-wait-preset]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.waitPreset)===settingsDraft.waitMinutes));}});
document.addEventListener('input',e=>{if(e.target.closest('#settings-form')&&e.target.name==='wait-minutes'){settingsDraft.waitMinutes=Number(e.target.value);document.querySelectorAll('#settings-form [data-wait-preset]').forEach(b=>b.classList.toggle('chosen',Number(b.dataset.waitPreset)===settingsDraft.waitMinutes));}});
function saveSettings(next){
 if(!store.configure(next)){notify(store.s.notice);return false;}
 preferences={...preferences,...next,onboardingDone:true};const saved=writePreferences(storage,preferences);
 notify(saved?'设置已保存，下次进入会记住你的选择':'当前设置已应用，但浏览器禁止保存；下次需重新设置');return true;
}

store.subscribe(s=>{state=s;render();syncPriority();if(preferences.onboardingDone)phoneGuide?.sync(s);});
render();
setupWizard=new SetupWizard({getSettings:()=>({...preferences,roomCapacity:state.roomCapacity,waitMinutes:state.waitMinutes}),onSave:saveSettings});
phoneGuide=new PhoneGuide({notify,onNotice:kind=>{
 if(!preferences.onboardingDone){notify('请先完成新手引导；点击通知不会执行关机');return;}
 if(kind==='test'&&!document.querySelector('#priority-layer dialog')){phoneGuide.open();return;}
 navigate('overview');
 if(store.canConfirm())openPriority(true);else notify('已回到当前状态；旧通知不会执行关机');
}});
addEventListener('online',render);addEventListener('offline',render);
if(!preferences.onboardingDone)setupWizard.open();
if(new URLSearchParams(location.search).has('notice'))notify('从通知返回：本演示重新打开会重置人数，请以当前页面为准');
setInterval(()=>{if(preferences.onboardingDone&&state.playing)store.advance(state.speed);},1000);
